异常警报触发条件
函数 检测异常行为(用户画像, 当前请求, 历史记录) {
  异常标记 = []

  // 1. 短时间多次失败
  最近5分钟失败次数 = 统计失败(历史记录, 最近5分钟)
  如果 (最近5分钟失败次数 >= 3) {
    异常标记.追加({
      类型: "暴力破解",
      严重度: "高",
      建议: "立即锁定账户30分钟"
    })
  }

  // 2. 地理位置跳跃
  如果 (历史记录.长度 > 0) {
    上次位置 = 历史记录[-1].位置
    当前位置 = 当前请求.位置
    距离 = 计算距离(上次位置, 当前位置)
    时间差 = 当前请求.时间戳 - 历史记录[-1].时间戳

    如果 (距离 > 1000公里 AND 时间差 < 1小时) {
      异常标记.追加({
        类型: "位置跳跃",
        严重度: "中",
        建议: "要求用户二次确认"
      })
    }
  }

  // 3. 行为模式突变
  如果 (用户画像.历史信心分.长度 >= 20) {
    最近平均 = 平均值(用户画像.历史信心分[-20:].信心分)
    如果 (当前请求.计算得分 < 最近平均 - 30) {
      异常标记.追加({
        类型: "行为突变",
        严重度: "中",
        建议: "增强验证要求"
      })
    }
  }

  // 4. 敏感操作异常时段
  如果 (检测到敏感操作(当前请求)) {
    当前小时 = 提取小时(当前请求.时间戳)
    如果 (当前小时 >= 2 AND 当前小时 <= 5) {
      // 凌晨2-5点进行敏感操作
      异常标记.追加({
        类型: "异常时段",
        严重度: "中",
        建议: "人工审核"
      })
    }
  }

  返回 异常标记
}

函数 发送警报(警报信息) {
  // 根据级别选择通知方式
  如果 (警报信息.级别 == "高危") {
    发送邮件(管理员邮箱, 警报信息)
    发送短信(管理员手机, 警报信息)
    记录系统日志(警报信息)
  } 否则如果 (警报信息.级别 == "中危") {
    发送邮件(管理员邮箱, 警报信息)
    记录系统日志(警报信息)
  } 否则 {
    记录系统日志(警报信息)
  }
}
